SELECT COUNT(DISTINCT ar.business_id) FROM approval_record ar
WHERE ar.business_type = 'RESIGNATION' AND ar.approval_status = 1 AND ar.is_deleted = 0
AND ar.create_time >= #{startOfMonth} AND ar.create_time < #{endOfMonth}

SELECT COUNT(*) FROM employee WHERE is_deleted = 0
AND dept_id IN

    #{id}

SELECT COUNT(*) FROM employee WHERE is_deleted = 0
AND create_time >= #{startOfMonth} AND create_time < #{endOfMonth}
AND dept_id IN

    #{id}

SELECT COUNT(DISTINCT ar.business_id) FROM approval_record ar
INNER JOIN employee e ON ar.business_id = e.id
WHERE ar.business_type = 'RESIGNATION' AND ar.approval_status = 1 AND ar.is_deleted = 0
AND ar.create_time >= #{startOfMonth} AND ar.create_time < #{endOfMonth}
AND e.dept_id IN

    #{id}

SELECT COUNT(*) FROM employee WHERE is_deleted = 0 AND status = 1
AND dept_id IN

    #{id}

SELECT d.id as deptId, d.name as deptName, COUNT(e.id) as employeeCount FROM department d LEFT JOIN employee e ON d.id = e.dept_id AND e.is_deleted = 0 WHERE d.is_deleted = 0 AND d.id IN
#{id}
GROUP BY d.id, d.name ORDER BY employeeCount DESC

SELECT DATE_FORMAT(entry_date, '%Y-%m') as month, COUNT(*) as count FROM employee WHERE is_deleted = 0 AND entry_date IS NOT NULL AND entry_date >= DATE_SUB(DATE_FORMAT(CURDATE(), '%Y-%m-01'), INTERVAL 11 MONTH) AND dept_id IN
#{id}
GROUP BY DATE_FORMAT(entry_date, '%Y-%m') ORDER BY month ASC

SELECT COUNT(DISTINCT ar.business_id) FROM approval_record ar
INNER JOIN employee e ON ar.business_id = e.id
WHERE ar.business_type = 'RESIGNATION' AND ar.approval_status = 1 AND ar.is_deleted = 0
AND ar.create_time >= #{startOfMonth} AND ar.create_time < #{endOfMonth}
AND e.create_by = #{userId}
